 "content": "def transform(grid):
    # Each outer marker launches an outward diagonal ray; color cycles by its role.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = {3: 8, 8: 7, 7: 6, 6: 3}
    # locate nonzero non-center marks and extend away from the central 2x2 block
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v not in seeds:
                continue
            dr = -1 if r < h//2 else 1
            dc = -1 if c < w//2 else 1
            nv = seeds[v]
            rr, cc = r, c
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] not in (0, v):
                    break
                out[rr][cc] = nv
                rr += dr; cc += dc
    return out
