 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Each 2x2 block anchors four diagonal arms. The arms cycle the
    # corner marker colors: TL takes BL, TR takes TL, BL takes BR, BR takes TR.
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r+1) for cc in (c, c+1)):
                blocks.append((r,c))
    for r,c in blocks:
        coords = [(r-1,c-1), (r-1,c+2), (r+2,c-1), (r+2,c+2)]
        vals = [grid[a][b] if 0 <= a < h and 0 <= b < w else 0 for a,b in coords]
        tl,tr,bl,br = vals
        colors = [bl, tl, br, tr]
        dirs = [(-1,-1),(-1,1),(1,-1),(1,1)]
        for (a,b),color,(dr,dc),seed in zip(coords,colors,dirs,vals):
            if not (0 <= a < h and 0 <= b < w) or seed == 0 or color == 0:
                continue
            rr,cc=a,b
            while 0 <= rr < h and 0 <= cc < w:
                if grid[rr][cc] == 2: break
                out[rr][cc]=color
                rr+=dr; cc+=dc
    return out
